import { db } from "@/lib/db/db";
import { posSales, posSaleItems, products } from "@/lib/db/schema";
import { eq, desc, gte, lte, and, inArray } from "drizzle-orm";
import { NextRequest, NextResponse } from "next/server";
import { requireAdmin, requireAdminOnly } from "@/lib/server-auth";

interface SaleItemInput {
  productId: string;
  quantity: number;
}

// POST /api/pos/sales - Ring up a retail/rental sale at the till.
//
// `id` is generated by the TILL ITSELF (not left to the DB default) so the
// offline queue's retry-after-reconnect is idempotent: if this exact sale
// already landed (the first attempt succeeded but the response never made it
// back to the browser before the connection dropped), re-sending it is a
// no-op, not a duplicate charge. See lib/pos-queue.ts.
export async function POST(request: NextRequest) {
  const auth = await requireAdmin(request);
  if (auth.response) return auth.response;

  try {
    const body = await request.json();
    const { id, paymentMethod, items } = body as {
      id: string;
      paymentMethod: "cash" | "card";
      items: SaleItemInput[];
    };

    if (!id || !paymentMethod || !Array.isArray(items) || items.length === 0) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
    }

    // Already synced by an earlier attempt - return it as-is rather than
    // erroring, so a queued retry after reconnect always succeeds.
    const existing = await db.select().from(posSales).where(eq(posSales.id, id)).limit(1);
    if (existing.length) {
      const existingItems = await db.select().from(posSaleItems).where(eq(posSaleItems.saleId, id));
      return NextResponse.json({ sale: existing[0], items: existingItems }, { status: 200 });
    }

    const catalog = await db.select().from(products);
    const catalogById = new Map(catalog.map((p) => [p.id, p]));

    let totalLkr = 0;
    const lineItems: (typeof posSaleItems.$inferInsert)[] = [];
    for (const item of items) {
      const product = catalogById.get(item.productId);
      if (!product) {
        return NextResponse.json({ error: `Unknown product: ${item.productId}` }, { status: 400 });
      }
      const unitPrice = Number(product.priceLkr);
      const lineTotal = unitPrice * item.quantity;
      totalLkr += lineTotal;
      lineItems.push({
        id: crypto.randomUUID(),
        saleId: id,
        productId: product.id,
        productName: product.name,
        quantity: item.quantity,
        unitPriceLkr: String(unitPrice),
        lineTotalLkr: String(lineTotal),
      });
    }

    const inserted = await db
      .insert(posSales)
      .values({
        id,
        soldByUserId: auth.user.id,
        paymentMethod,
        totalLkr: String(totalLkr),
      })
      .onConflictDoNothing()
      .returning();

    // A race with another concurrent sync of the same id - treat exactly
    // like the already-synced check above.
    if (!inserted.length) {
      const race = await db.select().from(posSales).where(eq(posSales.id, id)).limit(1);
      const raceItems = await db.select().from(posSaleItems).where(eq(posSaleItems.saleId, id));
      return NextResponse.json({ sale: race[0], items: raceItems }, { status: 200 });
    }

    await db.insert(posSaleItems).values(lineItems);

    return NextResponse.json({ sale: inserted[0], items: lineItems }, { status: 201 });
  } catch (error) {
    console.error("Create POS sale error:", error);
    return NextResponse.json({ error: "Failed to record sale" }, { status: 500 });
  }
}

// GET /api/pos/sales - Admin-only: sales for the Reports page's POS
// section. Optional ?startDate=&endDate= (yyyy-mm-dd, inclusive).
export async function GET(request: NextRequest) {
  const auth = await requireAdminOnly(request);
  if (auth.response) return auth.response;

  try {
    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get("startDate");
    const endDate = searchParams.get("endDate");

    const conditions = [];
    if (startDate) conditions.push(gte(posSales.createdAt, new Date(startDate)));
    if (endDate) conditions.push(lte(posSales.createdAt, new Date(`${endDate}T23:59:59`)));

    const sales = await db
      .select()
      .from(posSales)
      .where(conditions.length ? and(...conditions) : undefined)
      .orderBy(desc(posSales.createdAt));

    const saleIds = sales.map((s) => s.id);
    const allItems = saleIds.length
      ? await db.select().from(posSaleItems).where(inArray(posSaleItems.saleId, saleIds))
      : [];
    const itemsBySale = new Map<string, typeof allItems>();
    for (const item of allItems) {
      const list = itemsBySale.get(item.saleId);
      if (list) list.push(item);
      else itemsBySale.set(item.saleId, [item]);
    }

    return NextResponse.json({
      sales: sales.map((s) => ({ ...s, items: itemsBySale.get(s.id) ?? [] })),
    });
  } catch (error) {
    console.error("Get POS sales error:", error);
    return NextResponse.json({ error: "Failed to fetch sales" }, { status: 500 });
  }
}
